#include <stdbool.h>

typedef struct {
    long long x, y;
} Point;

long long dist_sq(Point a, Point b) {
    long long dx = a.x - b.x;
    long long dy = a.y - b.y;
    return dx * dx + dy * dy;
}

long long dot_product(Point a, Point b, Point c) {
    // Vetor ba . bc
